import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BBXLvvRa.js";const f=JSON.parse('{"title":"How To Contribute","description":"Contribution Guidelines","frontmatter":{"title":"How To Contribute","description":"Contribution Guidelines"},"headers":[],"relativePath":"docs/contributing.md","filePath":"docs/contributing.md"}'),i={name:"docs/contributing.md"};function n(s,e,c,u,d,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-to-contribute" tabindex="-1">How To Contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How To Contribute&quot;">​</a></h1><p>There are several ways, how you can participate in this community.</p><h2 id="interested" tabindex="-1">Interested? <a class="header-anchor" href="#interested" aria-label="Permalink to &quot;Interested?&quot;">​</a></h2><p>We would love to receive feedback and discuss different aspects of BPM with you. For this purpose, we opened a <a href="https://github.com/bpm-crafters/bpm-crafters/discussions" target="_blank" rel="noreferrer">Discussion</a> section for you. If you have any questions, contributions or ideas, please don&#39;t hesitate to join our discussion.</p><h2 id="sign-the-manifesto" tabindex="-1">Sign the Manifesto <a class="header-anchor" href="#sign-the-manifesto" aria-label="Permalink to &quot;Sign the Manifesto&quot;">​</a></h2><p>You think that BPM Manifesto is essential for BPM solutions and community and share our values? You can make it public by signing the Manifesto and your name will appear on the <a href="https://bpm-crafters.dev/docs/hall-of-signatories" target="_blank" rel="noreferrer">Hall of Signatories</a>. Please open a discussion in <a href="https://github.com/bpm-crafters/bpm-crafters/discussions/categories/request-for-hall-of-signatories" target="_blank" rel="noreferrer">Request for Hall of Signatories</a> and provide your name, optionally your company&#39;s name and, if you like a short statement, which should appear on the page.</p><h2 id="become-an-active-contributor" tabindex="-1">Become an active contributor <a class="header-anchor" href="#become-an-active-contributor" aria-label="Permalink to &quot;Become an active contributor&quot;">​</a></h2><p>If you are interested in sharing your experience and want actively participate on content and solution creation of BPM crafters, we welcome you to become an active contributor. Please send us an email at <a href="mailto:contribute@bpm-crafters.dev">contribute@bpm-crafters.dev</a>.</p><h2 id="stay-informed" tabindex="-1">Stay informed <a class="header-anchor" href="#stay-informed" aria-label="Permalink to &quot;Stay informed&quot;">​</a></h2><p>We envision to provide regularly updates about progress of the Manifesto, new content of BPM crafters and will develop a solution for this. For now, just write us an email at <a href="mailto:stay-informed@bpm-crafters.dev">stay-informed@bpm-crafters.dev</a>.</p>',10)])])}const p=t(i,[["render",n]]);export{f as __pageData,p as default};
